--
-- Name: auto_reconstruct_trajectory(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_reconstruct_trajectory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE

    prev_event RECORD;
    route_info RECORD;

    previous_trajectory_id BIGINT;
    new_trajectory_id BIGINT;

    actual_travel_seconds DOUBLE PRECISION;
    minimum_physical_time_seconds DOUBLE PRECISION;

    trajectory_confidence NUMERIC;

BEGIN

    -- ========================================================
    -- 1. Find previous observation
    -- ========================================================

    SELECT
        e.event_id,
        e.vehicle_id,
        e.camera_id,
        e.observed_at,
        e.confidence,
        e.location
    INTO prev_event

    FROM events e

    WHERE e.vehicle_id = NEW.vehicle_id
      AND e.event_id <> NEW.event_id
      AND e.observed_at < NEW.observed_at
      AND e.camera_id <> NEW.camera_id

    ORDER BY
        e.observed_at DESC,
        e.event_id DESC

    LIMIT 1;


    IF NOT FOUND THEN
        RETURN NEW;
    END IF;


    -- ========================================================
    -- 2. Calculate travel time
    -- ========================================================

    actual_travel_seconds :=
        EXTRACT(
            EPOCH FROM
            (NEW.observed_at - prev_event.observed_at)
        );


    IF actual_travel_seconds <= 0 THEN
        RETURN NEW;
    END IF;


    -- ========================================================
    -- 3. Find predefined route
    -- ========================================================

    SELECT
        cr.route_id,
        cr.starting_node,
        cr.ending_node,
        cr.road_list,
        cr.total_distance_m,
        cr.geometry

    INTO route_info

    FROM camera_routes cr

    WHERE cr.starting_node = prev_event.camera_id
      AND cr.ending_node = NEW.camera_id

    ORDER BY cr.route_id

    LIMIT 1;


    IF NOT FOUND THEN

        RAISE NOTICE
            'No predefined route: % -> %',
            prev_event.camera_id,
            NEW.camera_id;

        RETURN NEW;

    END IF;


    -- ========================================================
    -- 4. Physical feasibility
    --
    -- Maximum physically reasonable speed = 120 km/h
    --
    -- This check remains here because a physically impossible
    -- observation should not become a valid trajectory.
    --
    -- Historical travel-time anomaly detection is NOT done here.
    -- ========================================================

    IF route_info.total_distance_m IS NULL
       OR route_info.total_distance_m <= 0 THEN

        RAISE NOTICE
            'Invalid route distance: % -> %',
            prev_event.camera_id,
            NEW.camera_id;

        RETURN NEW;

    END IF;


    minimum_physical_time_seconds :=
        route_info.total_distance_m
        / (120000.0 / 3600.0);


    IF actual_travel_seconds < minimum_physical_time_seconds THEN

        RAISE NOTICE
            'Trajectory rejected: physically impossible. % -> %. Actual=% sec, minimum=% sec.',
            prev_event.camera_id,
            NEW.camera_id,
            ROUND(actual_travel_seconds),
            ROUND(minimum_physical_time_seconds);

        RETURN NEW;

    END IF;


    -- ========================================================
    -- 5. Calculate trajectory confidence
    --
    -- Historical statistics are intentionally NOT used here.
    -- Route anomaly detection handles historical deviation.
    -- ========================================================

    trajectory_confidence :=
        (
            COALESCE(prev_event.confidence, 0)
            +
            COALESCE(NEW.confidence, 0)
        ) / 2.0;


    -- Keep confidence between 0 and 1

    trajectory_confidence :=
        LEAST(
            GREATEST(
                ROUND(trajectory_confidence, 2),
                0
            ),
            1
        );


    -- ========================================================
    -- 6. Find previous trajectory
    -- ========================================================

    SELECT
        t.trajectory_id

    INTO previous_trajectory_id

    FROM trajectories t

    WHERE t.vehicle_id = prev_event.vehicle_id::BIGINT
      AND t.to_camera_id = prev_event.camera_id
      AND t.end_event_id = prev_event.event_id

    ORDER BY t.ended_at DESC

    LIMIT 1;


    -- ========================================================
    -- 7. Create trajectory
    -- ========================================================

        vehicle_id,
        start_event_id,
        end_event_id,
        from_camera_id,
        to_camera_id,
        started_at,
        ended_at,
        travel_time_seconds,
        distance_m,
        road_sequence,
        geometry,
        inference_method,
        confidence
    )

    VALUES
    (
        NEW.vehicle_id::BIGINT,

        prev_event.event_id,
        NEW.event_id,

        prev_event.camera_id,
        NEW.camera_id,

        prev_event.observed_at,
        NEW.observed_at,

        actual_travel_seconds,

        route_info.total_distance_m,

        route_info.road_list,

        ST_LineMerge(route_info.geometry),

        'PREDEFINED_CAMERA_ROUTE',

        trajectory_confidence
    )

    RETURNING trajectory_id
    INTO new_trajectory_id;


    -- ========================================================
    -- 8. Notify downstream real-time systems
    -- ========================================================

    PERFORM pg_notify(
        'trajectory_created',
        json_build_object(
            'trajectory_id', new_trajectory_id,
            'vehicle_id', NEW.vehicle_id,
            'from_camera_id', prev_event.camera_id,
            'to_camera_id', NEW.camera_id,
            'start_event_id', prev_event.event_id,
            'end_event_id', NEW.event_id
        )::text
    );


    -- ========================================================
    -- 9. Link trajectories
    -- ========================================================

    IF previous_trajectory_id IS NOT NULL THEN

        UPDATE trajectories
        SET next_trajectory_id = new_trajectory_id
        WHERE trajectory_id = previous_trajectory_id;


        UPDATE trajectories
        SET prev_trajectory_id = previous_trajectory_id
        WHERE trajectory_id = new_trajectory_id;

    END IF;


    RETURN NEW;


EXCEPTION
    WHEN OTHERS THEN

        RAISE WARNING
            'Trajectory reconstruction failed for event %: %',
            NEW.event_id,
            SQLERRM;

        RETURN NEW;

END;

$$;


