-- Name: auto_register_vehicle(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_register_vehicle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

    -- Check whether this plate already exists
    IF NOT EXISTS (
        SELECT 1
        FROM vehicles
        WHERE plate_number = NEW.plate_number
    ) THEN

        -- Register new vehicle
            plate_number
        )
        VALUES (
            NEW.plate_number
        );

    END IF;

    RETURN NEW;
END;
$$;


