--
-- Name: process_trajectory_for_trip(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.process_trajectory_for_trip(p_trajectory_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    traj RECORD;
    latest_trip RECORD;
    gap_seconds NUMERIC;
    trip_gap_limit_seconds NUMERIC := 1800; -- 30 minutes
BEGIN

    -- 1. Get the trajectory
    SELECT
        t.trajectory_id,
        t.vehicle_id,
        t.from_camera_id,
        t.to_camera_id,
        t.started_at,
        t.ended_at,
        t.travel_time_seconds,
        t.distance_m
    INTO traj
    FROM trajectories t
    WHERE t.trajectory_id = p_trajectory_id;

    IF NOT FOUND THEN
        RAISE NOTICE 'Trajectory % does not exist.', p_trajectory_id;
        RETURN;
    END IF;


    -- 2. Find the latest trip for this vehicle
    SELECT *
    INTO latest_trip
    FROM trips
    WHERE vehicle_id = traj.vehicle_id
    ORDER BY trip_id DESC
    LIMIT 1;


    -- 3. No existing trip → create one
    IF NOT FOUND THEN

            vehicle_id,
            origin_camera_id,
            destination_camera_id,
            started_at,
            ended_at,
            total_distance_m,
            total_travel_time_seconds,
            segment_count,
            last_trajectory_id
        )
        VALUES (
            traj.vehicle_id,
            traj.from_camera_id,
            traj.to_camera_id,
            traj.started_at,
            traj.ended_at,
            traj.distance_m,
            traj.travel_time_seconds,
            1,
            traj.trajectory_id
        );

        RAISE NOTICE
            'Created new trip for vehicle %.',
            traj.vehicle_id;

        RETURN;
    END IF;


    -- 4. Duplicate protection
    IF latest_trip.last_trajectory_id = traj.trajectory_id THEN

        RAISE NOTICE
            'Trajectory % already processed.',
            p_trajectory_id;

        RETURN;
    END IF;


    -- 5. Make sure the new trajectory connects
    --    to the current trip
    IF latest_trip.destination_camera_id <> traj.from_camera_id THEN

            vehicle_id,
            origin_camera_id,
            destination_camera_id,
            started_at,
            ended_at,
            total_distance_m,
            total_travel_time_seconds,
            segment_count,
            last_trajectory_id
        )
        VALUES (
            traj.vehicle_id,
            traj.from_camera_id,
            traj.to_camera_id,
            traj.started_at,
            traj.ended_at,
            traj.distance_m,
            traj.travel_time_seconds,
            1,
            traj.trajectory_id
        );

        RAISE NOTICE
            'Trajectory % does not connect. Created new trip.',
            p_trajectory_id;

        RETURN;
    END IF;


    -- 6. Calculate the time gap
    gap_seconds :=
        EXTRACT(
            EPOCH FROM
            (traj.started_at - latest_trip.ended_at)
        );


    -- 7. Large inactivity gap → new trip
    IF gap_seconds > trip_gap_limit_seconds THEN

            vehicle_id,
            origin_camera_id,
            destination_camera_id,
            started_at,
            ended_at,
            total_distance_m,
            total_travel_time_seconds,
            segment_count,
            last_trajectory_id
        )
        VALUES (
            traj.vehicle_id,
            traj.from_camera_id,
            traj.to_camera_id,
            traj.started_at,
            traj.ended_at,
            traj.distance_m,
            traj.travel_time_seconds,
            1,
            traj.trajectory_id
        );

        RAISE NOTICE
            'Gap %.0f seconds > 30 minutes. Created new trip.',
            gap_seconds;

        RETURN;
    END IF;


    -- 8. Same continuous trip → update
    UPDATE trips
    SET
        destination_camera_id = traj.to_camera_id,
        ended_at = traj.ended_at,

        total_distance_m =
            COALESCE(total_distance_m, 0)
            + COALESCE(traj.distance_m, 0),

        total_travel_time_seconds =
            COALESCE(total_travel_time_seconds, 0)
            + COALESCE(traj.travel_time_seconds, 0),

        segment_count =
            segment_count + 1,

        last_trajectory_id =
            traj.trajectory_id,

        updated_at =
            CURRENT_TIMESTAMP

    WHERE trip_id = latest_trip.trip_id;


    RAISE NOTICE
        'Updated trip % for vehicle %.',
        latest_trip.trip_id,
        traj.vehicle_id;

END;
$$;


